import React, { useState, useCallback, useRef } from 'react';
import { useQuery, gql } from '@apollo/client';
import {
  Container,
  Box,
  Typography,
  Card,
  CardContent,
  LinearProgress,
  CircularProgress,
  Button,
  Drawer,
  Fab,
  Tooltip,
} from '@mui/material';
import {
  Lock as LockIcon,
  LockOpen as LockOpenIcon,
  BatteryChargingFull as BatteryIcon,
  Speed as SpeedIcon,
  Build as BuildIcon,
  TireRepair as TireIcon,
  Refresh as RefreshIcon,
  Chat as ChatIcon,
} from '@mui/icons-material';
import toast from 'react-hot-toast';
import { ChatPanel } from '../components/ChatPanel';

const GET_USER = gql`
  query GetUser($email: String!) {
    user(email: $email) {
      email
      name
      vehicle {
        id
        model
        batteryLevel
        rangeKm
        totalKm
        nextServiceKm
        tirePressure
        softwareVersion
        isLocked
        lastUpdated
      }
    }
  }
`;

interface Vehicle {
  id: string;
  model: string;
  batteryLevel: number;
  rangeKm: number;
  totalKm: number;
  nextServiceKm: number;
  tirePressure: number;
  softwareVersion: string;
  isLocked: boolean;
  lastUpdated: string;
}

interface User {
  email: string;
  name: string;
  vehicle: Vehicle | null;
}

interface GetUserData {
  user: User | null;
}

interface OverviewProps {
  userEmail: string;
}

export const Overview: React.FC<OverviewProps> = ({ userEmail }) => {
  const { loading, error, data, refetch } = useQuery<GetUserData>(GET_USER, {
    variables: { email: userEmail },
    pollInterval: 30000,
    fetchPolicy: 'network-only',
    nextFetchPolicy: 'cache-and-network',
  });

  const [carImageError, setCarImageError] = useState(false);
  const [chatOpen, setChatOpen] = useState(false);
  const [drawerWidth, setDrawerWidth] = useState(420);
  const isResizing = useRef(false);

  const handleResizeStart = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    isResizing.current = true;

    const onMouseMove = (moveEvent: MouseEvent) => {
      if (!isResizing.current) return;
      const newWidth = window.innerWidth - moveEvent.clientX;
      setDrawerWidth(Math.min(Math.max(newWidth, 280), 800));
    };

    const onMouseUp = () => {
      isResizing.current = false;
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
    };

    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
  }, []);

  const handleRefresh = async () => {
    toast.loading('Fetching latest vehicle data...', {
      id: 'vehicle-refresh',
      style: { background: '#18181b', color: '#fafafa' },
    });

    try {
      await refetch();
      toast.success('Vehicle data updated', {
        id: 'vehicle-refresh',
        style: { background: '#18181b', color: '#fafafa' },
      });
    } catch (err) {
      toast.error('Failed to update vehicle data', {
        id: 'vehicle-refresh',
        style: { background: '#18181b', color: '#fafafa' },
      });
    }
  };

  if (loading) {
    return (
      <Box
        sx={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          minHeight: 'calc(100vh - 72px)',
        }}
      >
        <CircularProgress sx={{ color: '#0ea5e9' }} />
      </Box>
    );
  }

  if (error) {
    return (
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center',
          minHeight: 'calc(100vh - 72px)',
          gap: 2,
        }}
      >
        <Typography sx={{ color: '#fafafa' }}>
          Error loading vehicle data: {error.message}
        </Typography>
        <Button
          onClick={handleRefresh}
          startIcon={<RefreshIcon />}
          variant="outlined"
          sx={{ color: '#fafafa', borderColor: 'rgba(14, 165, 233, 0.45)' }}
        >
          Retry
        </Button>
      </Box>
    );
  }

  const user = data?.user;
  const vehicle = user?.vehicle;

  const cardSx = {
    elevation: 0,
    backgroundColor: 'rgba(255, 255, 255, 0.03)',
    backdropFilter: 'blur(15px)',
    borderRadius: 3,
    border: '1px solid rgba(255, 255, 255, 0.07)',
    overflow: 'hidden',
  };

  const statBoxSx = {
    p: 2,
    backgroundColor: 'rgba(0, 0, 0, 0.2)',
    borderRadius: 1,
    border: '1px solid rgba(255, 255, 255, 0.06)',
  };

  return (
    <>
      <Container maxWidth="md" sx={{ pt: 2, pb: 4 }}>
        <Card elevation={0} sx={cardSx}>
          <CardContent sx={{ p: 3 }}>
            {/* Vehicle model name */}
            <Box sx={{ textAlign: 'center', mb: 3 }}>
              <Typography
                sx={{
                  color: '#a1a1aa',
                  fontSize: '0.9rem',
                  fontWeight: 500,
                  letterSpacing: '0.1em',
                  textTransform: 'uppercase',
                }}
              >
                {vehicle?.model ?? 'No Vehicle'}
              </Typography>
            </Box>

            {/* Car image with ALL GOOD behind it */}
            <Box sx={{ position: 'relative', textAlign: 'center', mb: 3 }}>
              {/* ALL GOOD sits behind the car */}
              <Box sx={{ position: 'relative', zIndex: 0, mb: -14 }}>
                <Typography
                  sx={{
                    fontSize: '4.5rem',
                    fontWeight: 700,
                    color: 'rgba(14, 165, 233, 0.2)',
                    lineHeight: 1,
                    mb: 0.5,
                  }}
                >
                  ALL
                </Typography>
                <Typography
                  sx={{
                    fontSize: '4.5rem',
                    fontWeight: 700,
                    color: 'rgba(14, 165, 233, 0.2)',
                    lineHeight: 1,
                  }}
                >
                  GOOD
                </Typography>
              </Box>

              {/* Car image sits in front */}
              <Box sx={{ position: 'relative', zIndex: 1 }}>
                {!carImageError ? (
                  <img
                    src={`${process.env.PUBLIC_URL}/images/porsche.png`}
                    alt="Vehicle"
                    onError={() => setCarImageError(true)}
                    style={{
                      width: '100%',
                      maxWidth: '500px',
                      height: 'auto',
                    }}
                  />
                ) : (
                  <Box
                    sx={{
                      display: 'inline-flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      width: '100%',
                      maxWidth: 500,
                      height: 200,
                      backgroundColor: 'rgba(14, 165, 233, 0.04)',
                      borderRadius: 2,
                      border: '2px dashed rgba(14, 165, 233, 0.22)',
                    }}
                  >
                    <Typography sx={{ color: 'rgba(14, 165, 233, 0.45)', fontSize: '0.9rem' }}>
                      Car Image
                    </Typography>
                  </Box>
                )}
              </Box>
            </Box>

            {/* Lock status */}
            <Box sx={{ textAlign: 'center', mb: 3 }}>
              <Box
                sx={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: 48,
                  height: 48,
                  borderRadius: '50%',
                  border: '2px solid rgba(14, 165, 233, 0.4)',
                  mb: 1,
                }}
              >
                {vehicle?.isLocked ? (
                  <LockIcon sx={{ color: '#0ea5e9', fontSize: 24 }} />
                ) : (
                  <LockOpenIcon sx={{ color: '#0ea5e9', fontSize: 24 }} />
                )}
              </Box>
              <Typography sx={{ color: '#a1a1aa', fontSize: '0.8rem' }}>
                {vehicle?.isLocked ? 'Locked' : 'Unlocked'}
              </Typography>
              {vehicle?.lastUpdated && (
                <Typography
                  variant="caption"
                  sx={{
                    color: 'rgba(126, 168, 201, 0.6)',
                    fontSize: '0.75rem',
                    display: 'block',
                    mt: 0.5,
                  }}
                >
                  Updated: {new Date(vehicle.lastUpdated).toLocaleString()}
                </Typography>
              )}
            </Box>

            {/* Battery level */}
            <Box sx={{ mt: 2 }}>
              <Box
                sx={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  mb: 1,
                }}
              >
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <BatteryIcon sx={{ color: '#0ea5e9', fontSize: 20 }} />
                  <Typography sx={{ color: '#fafafa', fontSize: '0.9rem' }}>Battery</Typography>
                </Box>
                <Typography sx={{ color: '#fafafa', fontSize: '1.1rem', fontWeight: 600 }}>
                  {vehicle?.batteryLevel ?? 0}
                  <span style={{ fontSize: '0.85rem' }}> %</span>
                </Typography>
              </Box>
              <LinearProgress
                variant="determinate"
                value={vehicle?.batteryLevel ?? 0}
                sx={{
                  height: 6,
                  borderRadius: 1,
                  backgroundColor: 'rgba(14, 165, 233, 0.15)',
                  '& .MuiLinearProgress-bar': {
                    backgroundColor: '#0ea5e9',
                    borderRadius: 1,
                  },
                }}
              />
            </Box>

            {/* Stats grid: 2x2 */}
            <Box
              sx={{
                mt: 3,
                display: 'grid',
                gridTemplateColumns: 'repeat(2, 1fr)',
                gap: 2,
              }}
            >
              <Box sx={statBoxSx}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, mb: 0.5 }}>
                  <SpeedIcon sx={{ color: 'rgba(14, 165, 233, 0.6)', fontSize: 14 }} />
                  <Typography sx={{ color: '#a1a1aa', fontSize: '0.75rem' }}>Range</Typography>
                </Box>
                <Typography sx={{ color: '#fafafa', fontSize: '1.2rem', fontWeight: 600 }}>
                  {vehicle?.rangeKm?.toLocaleString() ?? 0} km
                </Typography>
              </Box>

              <Box sx={statBoxSx}>
                <Typography sx={{ color: '#a1a1aa', fontSize: '0.75rem', mb: 0.5 }}>
                  Total km
                </Typography>
                <Typography sx={{ color: '#fafafa', fontSize: '1.2rem', fontWeight: 600 }}>
                  {vehicle?.totalKm?.toLocaleString() ?? 0} km
                </Typography>
              </Box>

              <Box sx={statBoxSx}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, mb: 0.5 }}>
                  <BuildIcon sx={{ color: 'rgba(14, 165, 233, 0.6)', fontSize: 14 }} />
                  <Typography sx={{ color: '#a1a1aa', fontSize: '0.75rem' }}>
                    Next Service
                  </Typography>
                </Box>
                <Typography sx={{ color: '#fafafa', fontSize: '1.2rem', fontWeight: 600 }}>
                  {vehicle?.nextServiceKm?.toLocaleString() ?? 0} km
                </Typography>
              </Box>

              <Box sx={statBoxSx}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, mb: 0.5 }}>
                  <TireIcon sx={{ color: 'rgba(14, 165, 233, 0.6)', fontSize: 14 }} />
                  <Typography sx={{ color: '#a1a1aa', fontSize: '0.75rem' }}>
                    Tire Pressure
                  </Typography>
                </Box>
                <Typography sx={{ color: '#fafafa', fontSize: '1.2rem', fontWeight: 600 }}>
                  {vehicle?.tirePressure ?? 0} Bar
                </Typography>
              </Box>
            </Box>

            {/* Refresh button */}
            <Box sx={{ mt: 3, textAlign: 'center' }}>
              <Button
                onClick={handleRefresh}
                startIcon={<RefreshIcon />}
                variant="outlined"
                size="small"
                sx={{
                  color: '#a1a1aa',
                  borderColor: 'rgba(14, 165, 233, 0.3)',
                  textTransform: 'none',
                  '&:hover': {
                    borderColor: 'rgba(14, 165, 233, 0.6)',
                    backgroundColor: 'rgba(14, 165, 233, 0.07)',
                  },
                }}
              >
                Refresh
              </Button>
            </Box>
          </CardContent>
        </Card>
      </Container>

      {/* Chat FAB */}
      <Tooltip title="Chat with your Car" placement="left">
        <Fab
          onClick={() => setChatOpen(true)}
          sx={{
            position: 'fixed',
            bottom: 32,
            right: 32,
            backgroundColor: '#0ea5e9',
            color: '#fff',
            '&:hover': {
              backgroundColor: '#0284c7',
            },
          }}
        >
          <ChatIcon />
        </Fab>
      </Tooltip>

      {/* Chat Drawer */}
      <Drawer
        anchor="right"
        open={chatOpen}
        onClose={() => setChatOpen(false)}
        PaperProps={{
          sx: {
            width: { xs: '100vw', sm: drawerWidth },
            height: '100vh',
            backgroundColor: '#09090b',
            backgroundImage: 'none',
            borderLeft: '1px solid rgba(255, 255, 255, 0.07)',
            display: 'flex',
            flexDirection: 'row',
            p: 0,
            boxSizing: 'border-box',
            overflow: 'hidden',
          },
        }}
      >
        {/* Resize handle */}
        <Box
          onMouseDown={handleResizeStart}
          sx={{
            width: 4,
            flexShrink: 0,
            cursor: 'col-resize',
            backgroundColor: 'transparent',
            transition: 'background-color 0.15s',
            '&:hover': { backgroundColor: 'rgba(14, 165, 233, 0.4)' },
            '&:active': { backgroundColor: 'rgba(14, 165, 233, 0.7)' },
          }}
        />

        {/* Content — matches the main page vertical rhythm: pt aligns with nav + container top */}
        <Box
          sx={{
            flex: 1,
            minWidth: 0,
            display: 'flex',
            flexDirection: 'column',
            pt: '80px',
            pb: 4,
            pr: 2,
            pl: 1,
            boxSizing: 'border-box',
          }}
        >
          <Box
            sx={{
              flex: 1,
              minHeight: 0,
              display: 'flex',
              flexDirection: 'column',
              backgroundColor: 'rgba(255, 255, 255, 0.03)',
              backdropFilter: 'blur(15px)',
              borderRadius: 3,
              border: '1px solid rgba(255, 255, 255, 0.07)',
              overflow: 'hidden',
              p: 2.5,
            }}
          >
            <ChatPanel vehicleId={vehicle?.id} height="100%" onClose={() => setChatOpen(false)} />
          </Box>
        </Box>
      </Drawer>
    </>
  );
};
